// PLENÁRIO PT — Constituição da República Portuguesa (texto em vigor, VII revisão, 2005).
// Resumos próximos da redação oficial. limit288 indica a alínea do art. 288.º que protege o conteúdo essencial.
// Nota: as alíneas do art. 288.º seguem a tradição portuguesa e saltam a letra «k» (a–j, l–o: 14 alíneas).

const PF = 'Princípios fundamentais';
const DD = 'Direitos e deveres fundamentais';
const OE = 'Organização económica';
const OP = 'Organização do poder político';
const GR = 'Garantia e revisão da Constituição';

export const CRP_ARTICLES = [
  // ───────────── PRINCÍPIOS FUNDAMENTAIS ─────────────
  { n: 1, title: 'República Portuguesa', part: PF, limit288: 'b',
    text: 'Portugal é uma República soberana, baseada na dignidade da pessoa humana e na vontade popular e empenhada na construção de uma sociedade livre, justa e solidária.' },
  { n: 2, title: 'Estado de direito democrático', part: PF, limit288: 'j',
    text: 'A República Portuguesa é um Estado de direito democrático, baseado na soberania popular, no pluralismo de expressão e organização política democráticas, no respeito e na garantia de efetivação dos direitos e liberdades fundamentais e na separação e interdependência de poderes, visando a realização da democracia económica, social e cultural e o aprofundamento da democracia participativa.' },
  { n: 3, title: 'Soberania e legalidade', part: PF, limit288: null,
    text: 'A soberania, una e indivisível, reside no povo, que a exerce segundo as formas previstas na Constituição. O Estado subordina-se à Constituição e funda-se na legalidade democrática. A validade das leis e dos demais atos do Estado depende da sua conformidade com a Constituição.' },
  { n: 6, title: 'Estado unitário', part: PF, limit288: 'a',
    text: 'O Estado é unitário e respeita na sua organização e funcionamento o regime autonómico insular e os princípios da subsidiariedade, da autonomia das autarquias locais e da descentralização democrática da administração pública. Os arquipélagos dos Açores e da Madeira constituem regiões autónomas dotadas de estatutos político-administrativos e de órgãos de governo próprio.' },
  { n: 7, title: 'Relações internacionais', part: PF, limit288: 'a',
    text: 'Portugal rege-se nas relações internacionais pelos princípios da independência nacional, do respeito dos direitos do homem, dos direitos dos povos, da igualdade entre os Estados, da solução pacífica dos conflitos internacionais e da não ingerência nos assuntos internos dos outros Estados. Portugal empenha-se no reforço da identidade europeia e pode convencionar o exercício, em comum, em cooperação ou pelas instituições da União, dos poderes necessários à construção e aprofundamento da União Europeia.' },
  { n: 8, title: 'Direito internacional', part: PF, limit288: null,
    text: 'As normas e os princípios de direito internacional geral ou comum fazem parte integrante do direito português. As disposições dos tratados que regem a União Europeia e as normas emanadas das suas instituições são aplicáveis na ordem interna, nos termos definidos pelo direito da União, com respeito pelos princípios fundamentais do Estado de direito democrático.' },
  { n: 9, title: 'Tarefas fundamentais do Estado', part: PF, limit288: null,
    text: 'São tarefas fundamentais do Estado garantir a independência nacional, os direitos e liberdades fundamentais e o respeito pelos princípios do Estado de direito democrático; defender a democracia política; promover o bem-estar e a igualdade real entre os portugueses; proteger o património cultural, a natureza e o ambiente; assegurar o ensino e defender a língua portuguesa; promover o desenvolvimento harmonioso de todo o território e a igualdade entre homens e mulheres.' },
  { n: 10, title: 'Sufrágio universal e partidos políticos', part: PF, limit288: 'h',
    text: 'O povo exerce o poder político através do sufrágio universal, igual, direto, secreto e periódico, do referendo e das demais formas previstas na Constituição. Os partidos políticos concorrem para a organização e para a expressão da vontade popular, no respeito pelos princípios da independência nacional, da unidade do Estado e da democracia política.' },
  { n: 11, title: 'Símbolos nacionais e língua oficial', part: PF, limit288: null,
    text: 'A Bandeira Nacional, símbolo da soberania da República, da independência, unidade e integridade de Portugal, é a adotada pela República instaurada pela Revolução de 5 de Outubro de 1910. O Hino Nacional é A Portuguesa. A língua oficial é o Português.' },
  // ───────────── DIREITOS E DEVERES FUNDAMENTAIS ─────────────
  { n: 13, title: 'Princípio da igualdade', part: DD, limit288: 'd',
    text: 'Todos os cidadãos têm a mesma dignidade social e são iguais perante a lei. Ninguém pode ser privilegiado, beneficiado, prejudicado, privado de qualquer direito ou isento de qualquer dever em razão de ascendência, sexo, raça, língua, território de origem, religião, convicções políticas ou ideológicas, instrução, situação económica, condição social ou orientação sexual.' },
  { n: 18, title: 'Força jurídica', part: DD, limit288: 'd',
    text: 'Os preceitos constitucionais respeitantes aos direitos, liberdades e garantias são diretamente aplicáveis e vinculam as entidades públicas e privadas. A lei só pode restringi-los nos casos expressamente previstos na Constituição, limitando-se ao necessário para salvaguardar outros direitos ou interesses constitucionalmente protegidos. As leis restritivas têm caráter geral e abstrato, não podem ter efeito retroativo nem diminuir o conteúdo essencial dos preceitos constitucionais.' },
  { n: 19, title: 'Suspensão do exercício de direitos', part: DD, limit288: 'd',
    text: 'Os órgãos de soberania não podem suspender o exercício dos direitos, liberdades e garantias, salvo em caso de estado de sítio ou de estado de emergência, declarados na forma prevista na Constituição e com duração máxima de quinze dias, renovável. A declaração em caso algum pode afetar os direitos à vida, à integridade pessoal, à identidade pessoal, à capacidade civil e à cidadania, a não retroatividade da lei criminal, o direito de defesa dos arguidos e a liberdade de consciência e de religião.' },
  { n: 24, title: 'Direito à vida', part: DD, limit288: 'd',
    text: 'A vida humana é inviolável. Em caso algum haverá pena de morte.' },
  { n: 25, title: 'Direito à integridade pessoal', part: DD, limit288: 'd',
    text: 'A integridade moral e física das pessoas é inviolável. Ninguém pode ser submetido a tortura, nem a tratos ou penas cruéis, degradantes ou desumanos.' },
  { n: 26, title: 'Outros direitos pessoais', part: DD, limit288: 'd',
    text: 'A todos são reconhecidos os direitos à identidade pessoal, ao desenvolvimento da personalidade, à capacidade civil, à cidadania, ao bom nome e reputação, à imagem, à palavra, à reserva da intimidade da vida privada e familiar e à proteção legal contra quaisquer formas de discriminação. A privação da cidadania e as restrições à capacidade civil só podem efetuar-se nos casos e termos previstos na lei, não podendo ter como fundamento motivos políticos.' },
  { n: 27, title: 'Direito à liberdade e à segurança', part: DD, limit288: 'd',
    text: 'Todos têm direito à liberdade e à segurança. Ninguém pode ser total ou parcialmente privado da liberdade, a não ser em consequência de sentença judicial condenatória pela prática de ato punido por lei com pena de prisão ou de aplicação judicial de medida de segurança, salvas as exceções taxativamente previstas, como a detenção em flagrante delito ou a prisão preventiva.' },
  { n: 29, title: 'Aplicação da lei criminal', part: DD, limit288: 'd',
    text: 'Ninguém pode ser sentenciado criminalmente senão em virtude de lei anterior que declare punível a ação ou a omissão. Ninguém pode ser julgado mais do que uma vez pela prática do mesmo crime. As leis penais de conteúdo mais favorável ao arguido aplicam-se retroativamente.' },
  { n: 30, title: 'Limites das penas e das medidas de segurança', part: DD, limit288: 'd',
    text: 'Não pode haver penas nem medidas de segurança privativas ou restritivas da liberdade com caráter perpétuo ou de duração ilimitada ou indefinida. A responsabilidade penal é insuscetível de transmissão. Nenhuma pena envolve como efeito necessário a perda de quaisquer direitos civis, profissionais ou políticos.' },
  { n: 32, title: 'Garantias de processo criminal', part: DD, limit288: 'd',
    text: 'O processo criminal assegura todas as garantias de defesa, incluindo o recurso. Todo o arguido se presume inocente até ao trânsito em julgado da sentença de condenação, devendo ser julgado no mais curto prazo compatível com as garantias de defesa. São nulas todas as provas obtidas mediante tortura, coação ou ofensa da integridade física ou moral da pessoa.' },
  { n: 33, title: 'Expulsão, extradição e direito de asilo', part: DD, limit288: 'd',
    text: 'Não é admitida a expulsão de cidadãos portugueses do território nacional. Não é admitida a extradição por motivos políticos, nem por crimes a que corresponda pena de morte ou outra de que resulte lesão irreversível da integridade física. É garantido o direito de asilo aos estrangeiros e aos apátridas perseguidos ou gravemente ameaçados de perseguição em consequência da sua atividade em favor da democracia, da liberdade e dos direitos da pessoa humana.' },
  { n: 34, title: 'Inviolabilidade do domicílio e da correspondência', part: DD, limit288: 'd',
    text: 'O domicílio e o sigilo da correspondência e dos outros meios de comunicação privada são invioláveis. A entrada no domicílio contra a vontade do cidadão só pode ser ordenada pela autoridade judicial competente. É proibida toda a ingerência das autoridades públicas na correspondência e nas telecomunicações, salvos os casos previstos na lei em matéria de processo criminal.' },
  { n: 35, title: 'Utilização da informática', part: DD, limit288: 'd',
    text: 'Todos os cidadãos têm o direito de acesso aos dados informatizados que lhes digam respeito e de exigir a sua retificação. A informática não pode ser utilizada para tratamento de dados referentes a convicções filosóficas ou políticas, filiação partidária ou sindical, fé religiosa, vida privada e origem étnica, salvo consentimento expresso ou garantias legais. É proibida a atribuição de um número nacional único aos cidadãos.' },
  { n: 36, title: 'Família, casamento e filiação', part: DD, limit288: 'd',
    text: 'Todos têm o direito de constituir família e de contrair casamento em condições de plena igualdade. Os cônjuges têm iguais direitos e deveres quanto à capacidade civil e política e à manutenção e educação dos filhos. Os filhos não podem ser separados dos pais, salvo quando estes não cumpram os seus deveres fundamentais para com eles e sempre mediante decisão judicial.' },
  { n: 37, title: 'Liberdade de expressão e informação', part: DD, limit288: 'd',
    text: 'Todos têm o direito de exprimir e divulgar livremente o seu pensamento pela palavra, pela imagem ou por qualquer outro meio, bem como o direito de informar, de se informar e de ser informados, sem impedimentos nem discriminações. O exercício destes direitos não pode ser impedido ou limitado por qualquer tipo ou forma de censura.' },
  { n: 38, title: 'Liberdade de imprensa e meios de comunicação social', part: DD, limit288: 'd',
    text: 'É garantida a liberdade de imprensa. O Estado assegura a liberdade e a independência dos órgãos de comunicação social perante o poder político e o poder económico. O Estado assegura a existência e o funcionamento de um serviço público de rádio e de televisão.' },
  { n: 41, title: 'Liberdade de consciência, de religião e de culto', part: DD, limit288: 'c',
    text: 'A liberdade de consciência, de religião e de culto é inviolável. Ninguém pode ser perseguido, privado de direitos ou isento de obrigações ou deveres cívicos por causa das suas convicções ou prática religiosa. As igrejas e outras comunidades religiosas estão separadas do Estado e são livres na sua organização e no exercício das suas funções e do culto. É garantido o direito à objeção de consciência.' },
  { n: 43, title: 'Liberdade de aprender e ensinar', part: DD, limit288: 'd',
    text: 'É garantida a liberdade de aprender e ensinar. O Estado não pode programar a educação e a cultura segundo quaisquer diretrizes filosóficas, estéticas, políticas, ideológicas ou religiosas. O ensino público não será confessional. É garantido o direito de criação de escolas particulares e cooperativas.' },
  { n: 45, title: 'Direito de reunião e de manifestação', part: DD, limit288: 'd',
    text: 'Os cidadãos têm o direito de se reunir, pacificamente e sem armas, mesmo em lugares abertos ao público, sem necessidade de qualquer autorização. A todos os cidadãos é reconhecido o direito de manifestação.' },
  { n: 46, title: 'Liberdade de associação', part: DD, limit288: 'd',
    text: 'Os cidadãos têm o direito de, livremente e sem dependência de qualquer autorização, constituir associações, desde que não se destinem a promover a violência e os seus fins não sejam contrários à lei penal. Ninguém pode ser obrigado a fazer parte de uma associação. Não são consentidas associações armadas nem de tipo militar, militarizadas ou paramilitares, nem organizações racistas ou que perfilhem a ideologia fascista.' },
  { n: 47, title: 'Liberdade de escolha de profissão e acesso à função pública', part: DD, limit288: 'd',
    text: 'Todos têm o direito de escolher livremente a profissão ou o género de trabalho, salvas as restrições legais impostas pelo interesse coletivo ou inerentes à sua própria capacidade. Todos os cidadãos têm o direito de acesso à função pública, em condições de igualdade e liberdade, em regra por via de concurso.' },
  { n: 48, title: 'Participação na vida pública', part: DD, limit288: 'd',
    text: 'Todos os cidadãos têm o direito de tomar parte na vida política e na direção dos assuntos públicos do país, diretamente ou por intermédio de representantes livremente eleitos, e o direito de ser esclarecidos objetivamente sobre os atos do Estado e informados pelo Governo acerca da gestão dos assuntos públicos.' },
  { n: 49, title: 'Direito de sufrágio', part: DD, limit288: 'h',
    text: 'Têm direito de sufrágio todos os cidadãos maiores de dezoito anos, ressalvadas as incapacidades previstas na lei geral. O exercício do direito de sufrágio é pessoal e constitui um dever cívico.' },
  { n: 51, title: 'Associações e partidos políticos', part: DD, limit288: 'i',
    text: 'A liberdade de associação compreende o direito de constituir ou participar em partidos políticos e de, através deles, concorrer democraticamente para a formação da vontade popular. Ninguém pode estar inscrito simultaneamente em mais de um partido. Os partidos não podem usar denominações relacionadas com religiões nem emblemas confundíveis com símbolos nacionais ou religiosos, nem ter índole ou âmbito regional.' },
  { n: 53, title: 'Segurança no emprego', part: DD, limit288: 'e',
    text: 'É garantida aos trabalhadores a segurança no emprego, sendo proibidos os despedimentos sem justa causa ou por motivos políticos ou ideológicos.' },
  { n: 55, title: 'Liberdade sindical', part: DD, limit288: 'e',
    text: 'É reconhecida aos trabalhadores a liberdade sindical, condição e garantia da construção da sua unidade para defesa dos seus direitos e interesses, incluindo a liberdade de constituição de associações sindicais, de inscrição e de organização interna.' },
  { n: 57, title: 'Direito à greve e proibição do lock-out', part: DD, limit288: 'e',
    text: 'É garantido o direito à greve. Compete aos trabalhadores definir o âmbito de interesses a defender através da greve, não podendo a lei limitar esse âmbito. A lei define os serviços mínimos indispensáveis para ocorrer à satisfação de necessidades sociais impreteríveis. É proibido o lock-out.' },
  { n: 58, title: 'Direito ao trabalho', part: DD, limit288: 'e',
    text: 'Todos têm direito ao trabalho. Para o assegurar, incumbe ao Estado promover a execução de políticas de pleno emprego, a igualdade de oportunidades na escolha da profissão e a formação cultural e técnica e a valorização profissional dos trabalhadores.' },
  { n: 59, title: 'Direitos dos trabalhadores', part: DD, limit288: 'e',
    text: 'Todos os trabalhadores têm direito à retribuição do trabalho segundo a quantidade, natureza e qualidade, observando-se o princípio de que para trabalho igual salário igual; a condições de trabalho dignas; ao repouso, a um limite máximo da jornada, ao descanso semanal e a férias pagas; e à assistência material no desemprego involuntário. Incumbe ao Estado o estabelecimento e a atualização do salário mínimo nacional.' },
  { n: 63, title: 'Segurança social e solidariedade', part: DD, limit288: null,
    text: 'Todos têm direito à segurança social. Incumbe ao Estado organizar, coordenar e subsidiar um sistema de segurança social unificado e descentralizado, que proteja os cidadãos na doença, velhice, invalidez, viuvez e orfandade, bem como no desemprego e em todas as situações de falta ou diminuição de meios de subsistência ou de capacidade para o trabalho.' },
  { n: 64, title: 'Saúde', part: DD, limit288: null,
    text: 'Todos têm direito à proteção da saúde e o dever de a defender e promover. O direito à proteção da saúde é realizado através de um serviço nacional de saúde universal e geral e, tendo em conta as condições económicas e sociais dos cidadãos, tendencialmente gratuito.' },
  { n: 65, title: 'Habitação e urbanismo', part: DD, limit288: null,
    text: 'Todos têm direito, para si e para a sua família, a uma habitação de dimensão adequada, em condições de higiene e conforto e que preserve a intimidade pessoal e a privacidade familiar. Incumbe ao Estado programar e executar uma política de habitação, promover a construção de habitações económicas e sociais e estabelecer um sistema de renda compatível com o rendimento familiar e de acesso à habitação própria.' },
  { n: 66, title: 'Ambiente e qualidade de vida', part: DD, limit288: null,
    text: 'Todos têm direito a um ambiente de vida humano, sadio e ecologicamente equilibrado e o dever de o defender. Incumbe ao Estado prevenir e controlar a poluição, ordenar o território, promover o aproveitamento racional dos recursos naturais, salvaguardando a sua capacidade de renovação e a estabilidade ecológica, com respeito pelo princípio da solidariedade entre gerações.' },
  { n: 73, title: 'Educação, cultura e ciência', part: DD, limit288: null,
    text: 'Todos têm direito à educação e à cultura. O Estado promove a democratização da educação para que contribua para a igualdade de oportunidades, a superação das desigualdades económicas, sociais e culturais, o desenvolvimento da personalidade e o espírito de tolerância e de responsabilidade.' },
  { n: 74, title: 'Ensino', part: DD, limit288: null,
    text: 'Todos têm direito ao ensino com garantia do direito à igualdade de oportunidades de acesso e êxito escolar. Incumbe ao Estado assegurar o ensino básico universal, obrigatório e gratuito e estabelecer progressivamente a gratuitidade de todos os graus de ensino.' },
  { n: 75, title: 'Ensino público, particular e cooperativo', part: DD, limit288: null,
    text: 'O Estado criará uma rede de estabelecimentos públicos de ensino que cubra as necessidades de toda a população. O Estado reconhece e fiscaliza o ensino particular e cooperativo, nos termos da lei.' },
  { n: 76, title: 'Universidade e acesso ao ensino superior', part: DD, limit288: null,
    text: 'O regime de acesso ao ensino superior garante a igualdade de oportunidades e a democratização do sistema de ensino. As universidades gozam, nos termos da lei, de autonomia estatutária, científica, pedagógica, administrativa e financeira.' },
  // ───────────── ORGANIZAÇÃO ECONÓMICA ─────────────
  { n: 80, title: 'Princípios fundamentais da organização económica', part: OE, limit288: 'f',
    text: 'A organização económico-social assenta na subordinação do poder económico ao poder político democrático; na coexistência do setor público, do setor privado e do setor cooperativo e social; na liberdade de iniciativa e de organização empresarial no âmbito de uma economia mista; na propriedade pública dos recursos naturais e de meios de produção, de acordo com o interesse coletivo; e no planeamento democrático do desenvolvimento.' },
  { n: 81, title: 'Incumbências prioritárias do Estado', part: OE, limit288: null,
    text: 'Incumbe prioritariamente ao Estado promover o bem-estar e a qualidade de vida das pessoas, em especial das mais desfavorecidas; promover a justiça social e corrigir as desigualdades na distribuição da riqueza e do rendimento, nomeadamente através da política fiscal; assegurar o funcionamento eficiente dos mercados e a equilibrada concorrência entre as empresas; e promover a coesão económica e social de todo o território.' },
  { n: 82, title: 'Setores de propriedade dos meios de produção', part: OE, limit288: 'f',
    text: 'É garantida a coexistência de três setores de propriedade dos meios de produção: o setor público, cuja propriedade e gestão pertencem ao Estado ou a outras entidades públicas; o setor privado, cuja propriedade ou gestão pertence a pessoas singulares ou coletivas privadas; e o setor cooperativo e social.' },
  { n: 103, title: 'Sistema fiscal', part: OE, limit288: null,
    text: 'O sistema fiscal visa a satisfação das necessidades financeiras do Estado e uma repartição justa dos rendimentos e da riqueza. Os impostos são criados por lei, que determina a incidência, a taxa, os benefícios fiscais e as garantias dos contribuintes. Ninguém pode ser obrigado a pagar impostos que não hajam sido criados nos termos da Constituição, que tenham natureza retroativa ou cuja cobrança se não faça nos termos da lei.' },
  { n: 104, title: 'Impostos', part: OE, limit288: null,
    text: 'O imposto sobre o rendimento pessoal visa a diminuição das desigualdades e será único e progressivo, tendo em conta as necessidades e os rendimentos do agregado familiar. A tributação das empresas incide fundamentalmente sobre o seu rendimento real. A tributação do património deve contribuir para a igualdade entre os cidadãos. A tributação do consumo deve onerar os consumos de luxo.' },
  { n: 105, title: 'Orçamento', part: OE, limit288: null,
    text: 'O Orçamento do Estado contém a discriminação das receitas e despesas do Estado, incluindo as dos fundos e serviços autónomos, e o orçamento da segurança social. É elaborado de harmonia com as grandes opções em matéria de planeamento e prevê as receitas necessárias para cobrir as despesas.' },
  { n: 106, title: 'Elaboração do Orçamento', part: OE, limit288: null,
    text: 'A lei do Orçamento é elaborada, organizada, votada e executada, anualmente, de acordo com a respetiva lei de enquadramento. A proposta de Orçamento é apresentada pelo Governo e votada pela Assembleia da República nos prazos fixados na lei.' },
  // ───────────── ORGANIZAÇÃO DO PODER POLÍTICO ─────────────
  { n: 108, title: 'Titularidade e exercício do poder', part: OP, limit288: null,
    text: 'O poder político pertence ao povo e é exercido nos termos da Constituição.' },
  { n: 110, title: 'Órgãos de soberania', part: OP, limit288: 'j',
    text: 'São órgãos de soberania o Presidente da República, a Assembleia da República, o Governo e os Tribunais. A formação, a composição, a competência e o funcionamento dos órgãos de soberania são os definidos na Constituição.' },
  { n: 111, title: 'Separação e interdependência', part: OP, limit288: 'j',
    text: 'Os órgãos de soberania devem observar a separação e a interdependência estabelecidas na Constituição. Nenhum órgão de soberania, de região autónoma ou de poder local pode delegar os seus poderes noutros órgãos, a não ser nos casos e nos termos expressamente previstos na Constituição e na lei.' },
  { n: 113, title: 'Princípios gerais de direito eleitoral', part: OP, limit288: 'h',
    text: 'O sufrágio direto, secreto e periódico constitui a regra geral de designação dos titulares dos órgãos eletivos. O recenseamento eleitoral é oficioso, obrigatório, permanente e único. As campanhas regem-se pela liberdade de propaganda, igualdade de oportunidades das candidaturas, imparcialidade das entidades públicas e transparência das contas. A conversão dos votos em mandatos faz-se segundo o princípio da representação proporcional.' },
  { n: 114, title: 'Partidos políticos e direito de oposição', part: OP, limit288: 'i',
    text: 'Os partidos políticos participam nos órgãos baseados no sufrágio universal e direto, de acordo com a sua representatividade eleitoral. É reconhecido às minorias o direito de oposição democrática. Os partidos representados na Assembleia da República que não façam parte do Governo têm o direito de ser informados regular e diretamente pelo Governo sobre os principais assuntos de interesse público.' },
  { n: 115, title: 'Referendo', part: OP, limit288: null,
    text: 'Os cidadãos eleitores podem ser chamados a pronunciar-se diretamente, a título vinculativo, através de referendo, por decisão do Presidente da República, mediante proposta da Assembleia da República ou do Governo, ou por iniciativa de cidadãos dirigida à Assembleia. O referendo só tem efeito vinculativo quando o número de votantes for superior a metade dos eleitores inscritos. São excluídas as alterações à Constituição e as questões orçamentais, tributárias ou financeiras.' },
  { n: 117, title: 'Estatuto dos titulares de cargos políticos', part: OP, limit288: null,
    text: 'Os titulares de cargos políticos respondem política, civil e criminalmente pelas ações e omissões que pratiquem no exercício das suas funções. A lei dispõe sobre os seus deveres, responsabilidades e incompatibilidades e determina os crimes de responsabilidade, cujas sanções podem incluir a destituição do cargo ou a perda do mandato.' },
  { n: 118, title: 'Princípio da renovação', part: OP, limit288: null,
    text: 'Ninguém pode exercer a título vitalício qualquer cargo político de âmbito nacional, regional ou local. A lei pode determinar limites à renovação sucessiva de mandatos dos titulares de cargos políticos executivos.' },
  { n: 120, title: 'Presidente da República — Definição', part: OP, limit288: null,
    text: 'O Presidente da República representa a República Portuguesa, garante a independência nacional, a unidade do Estado e o regular funcionamento das instituições democráticas e é, por inerência, Comandante Supremo das Forças Armadas.' },
  { n: 121, title: 'Eleição do Presidente da República', part: OP, limit288: 'h',
    text: 'O Presidente da República é eleito por sufrágio universal, direto e secreto dos cidadãos portugueses eleitores recenseados no território nacional, bem como dos cidadãos portugueses residentes no estrangeiro, nos termos da lei.' },
  { n: 123, title: 'Reelegibilidade', part: OP, limit288: null,
    text: 'Não é admitida a reeleição para um terceiro mandato consecutivo, nem durante o quinquénio imediatamente subsequente ao termo do segundo mandato consecutivo.' },
  { n: 128, title: 'Mandato do Presidente da República', part: OP, limit288: null,
    text: 'O mandato do Presidente da República tem a duração de cinco anos e termina com a posse do novo Presidente eleito. Em caso de vagatura, o Presidente da República a eleger inicia um novo mandato.' },
  { n: 133, title: 'Competência quanto a outros órgãos', part: OP, limit288: null,
    text: 'Compete ao Presidente da República presidir ao Conselho de Estado; marcar o dia das eleições; dissolver a Assembleia da República, ouvidos os partidos nela representados e o Conselho de Estado; nomear o Primeiro-Ministro; demitir o Governo, nos termos do artigo 195.º; e nomear e exonerar os membros do Governo, sob proposta do Primeiro-Ministro.' },
  { n: 134, title: 'Competência para a prática de atos próprios', part: OP, limit288: null,
    text: 'Compete ao Presidente da República exercer as funções de Comandante Supremo das Forças Armadas; promulgar e mandar publicar as leis e os decretos-leis; submeter a referendo questões de relevante interesse nacional; declarar o estado de sítio ou de emergência; requerer ao Tribunal Constitucional a apreciação preventiva da constitucionalidade; e indultar e comutar penas.' },
  { n: 136, title: 'Promulgação e veto', part: OP, limit288: null,
    text: 'No prazo de vinte dias, o Presidente da República promulga os decretos da Assembleia da República ou exerce o direito de veto, em mensagem fundamentada. Se a Assembleia confirmar o voto por maioria absoluta dos Deputados em efetividade de funções, o Presidente deve promulgar em oito dias; para leis orgânicas e outras matérias é exigida maioria de dois terços. Os decretos do Governo são promulgados ou vetados em quarenta dias, sendo o veto, neste caso, insuperável.' },
  { n: 147, title: 'Assembleia da República — Definição', part: OP, limit288: null,
    text: 'A Assembleia da República é a assembleia representativa de todos os cidadãos portugueses.' },
  { n: 148, title: 'Composição da Assembleia', part: OP, limit288: null,
    text: 'A Assembleia da República tem o mínimo de cento e oitenta e o máximo de duzentos e trinta Deputados, nos termos da lei eleitoral.' },
  { n: 149, title: 'Círculos eleitorais', part: OP, limit288: 'h',
    text: 'Os Deputados são eleitos por círculos eleitorais geograficamente definidos na lei, a qual pode determinar a existência de círculos plurinominais e uninominais, por forma a assegurar o sistema de representação proporcional e o método da média mais alta de Hondt. O número de Deputados por círculo plurinominal é proporcional ao número de cidadãos eleitores nele inscritos.' },
  { n: 151, title: 'Candidaturas', part: OP, limit288: null,
    text: 'As candidaturas são apresentadas pelos partidos políticos, isoladamente ou em coligação, podendo as listas integrar cidadãos não inscritos nos respetivos partidos. Ninguém pode ser candidato por mais de um círculo eleitoral da mesma natureza ou figurar em mais de uma lista.' },
  { n: 152, title: 'Representação política', part: OP, limit288: 'h',
    text: 'A lei não pode estabelecer limites à conversão dos votos em mandatos por exigência de uma percentagem de votos nacional mínima. Os Deputados representam todo o país e não os círculos por que são eleitos.' },
  { n: 156, title: 'Poderes dos Deputados', part: OP, limit288: null,
    text: 'Constituem poderes dos Deputados apresentar projetos de revisão constitucional, projetos de lei e de resolução e propostas de alteração; requerer a apreciação parlamentar de decretos-leis; requerer e obter do Governo os elementos e informações que considerem úteis; formular perguntas ao Governo; e requerer a constituição de comissões parlamentares de inquérito.' },
  { n: 161, title: 'Competência política e legislativa da Assembleia', part: OP, limit288: null,
    text: 'Compete à Assembleia da República aprovar alterações à Constituição; fazer leis sobre todas as matérias, salvo as reservadas ao Governo; conferir autorizações legislativas; aprovar as grandes opções dos planos e o Orçamento do Estado, sob proposta do Governo; aprovar tratados; propor ao Presidente da República a sujeição a referendo; e autorizar e confirmar a declaração do estado de sítio e do estado de emergência.' },
  { n: 163, title: 'Competência quanto a outros órgãos', part: OP, limit288: null,
    text: 'Compete à Assembleia da República testemunhar a posse do Presidente da República; apreciar o programa do Governo; votar moções de confiança e de censura; e eleger, por maioria de dois terços, dez juízes do Tribunal Constitucional, o Provedor de Justiça, o Presidente do Conselho Económico e Social e membros do Conselho Superior da Magistratura.' },
  { n: 164, title: 'Reserva absoluta de competência legislativa', part: OP, limit288: null,
    text: 'É da exclusiva competência da Assembleia da República legislar sobre as eleições dos titulares dos órgãos de soberania, os referendos, a organização do Tribunal Constitucional, a defesa nacional, o estado de sítio e de emergência, a aquisição e perda da cidadania portuguesa, os partidos políticos e o regime das forças de segurança, entre outras matérias.' },
  { n: 165, title: 'Reserva relativa de competência legislativa', part: OP, limit288: null,
    text: 'É da exclusiva competência da Assembleia da República, salvo autorização ao Governo, legislar sobre direitos, liberdades e garantias; definição dos crimes e das penas e processo criminal; bases da segurança social e do serviço nacional de saúde; criação de impostos e sistema fiscal; definição dos setores de propriedade dos meios de produção; e bases do sistema de ensino, entre outras.' },
  { n: 166, title: 'Forma dos atos', part: OP, limit288: null,
    text: 'Revestem a forma de lei constitucional as alterações à Constituição. Revestem a forma de lei orgânica, entre outros, os atos sobre eleições, referendos, Tribunal Constitucional, defesa nacional, estado de sítio, cidadania, partidos políticos e a criação das regiões administrativas.' },
  { n: 168, title: 'Discussão e votação', part: OP, limit288: null,
    text: 'A discussão dos projetos e propostas de lei compreende um debate na generalidade e outro na especialidade. A votação compreende uma votação na generalidade, uma votação na especialidade e uma votação final global. As leis orgânicas carecem de aprovação, na votação final global, por maioria absoluta dos Deputados em efetividade de funções.' },
  { n: 172, title: 'Dissolução da Assembleia', part: OP, limit288: null,
    text: 'A Assembleia da República não pode ser dissolvida nos seis meses posteriores à sua eleição, no último semestre do mandato do Presidente da República ou durante a vigência do estado de sítio ou do estado de emergência. A inobservância destes limites determina a inexistência jurídica do decreto de dissolução.' },
  { n: 182, title: 'Governo — Definição', part: OP, limit288: null,
    text: 'O Governo é o órgão de condução da política geral do país e o órgão superior da administração pública.' },
  { n: 183, title: 'Composição do Governo', part: OP, limit288: null,
    text: 'O Governo é constituído pelo Primeiro-Ministro, pelos Ministros e pelos Secretários e Subsecretários de Estado, podendo incluir Vice-Primeiros-Ministros. O número, a designação e as atribuições dos ministérios são determinados pelos decretos de nomeação ou por decreto-lei.' },
  { n: 186, title: 'Início e cessação de funções', part: OP, limit288: null,
    text: 'As funções do Primeiro-Ministro iniciam-se com a sua posse e cessam com a sua exoneração pelo Presidente da República. Antes da apreciação do seu programa pela Assembleia da República, ou após a sua demissão, o Governo limita-se à prática dos atos estritamente necessários para assegurar a gestão dos negócios públicos.' },
  { n: 187, title: 'Formação do Governo', part: OP, limit288: null,
    text: 'O Primeiro-Ministro é nomeado pelo Presidente da República, ouvidos os partidos representados na Assembleia da República e tendo em conta os resultados eleitorais. Os restantes membros do Governo são nomeados pelo Presidente da República, sob proposta do Primeiro-Ministro.' },
  { n: 190, title: 'Responsabilidade do Governo', part: OP, limit288: null,
    text: 'O Governo é responsável perante o Presidente da República e a Assembleia da República.' },
  { n: 192, title: 'Apreciação do programa do Governo', part: OP, limit288: null,
    text: 'O programa do Governo é submetido à apreciação da Assembleia da República no prazo máximo de dez dias após a nomeação do Primeiro-Ministro. O debate não pode exceder três dias e qualquer grupo parlamentar pode propor a rejeição do programa. A rejeição exige maioria absoluta dos Deputados em efetividade de funções.' },
  { n: 193, title: 'Solicitação de voto de confiança', part: OP, limit288: null,
    text: 'O Governo pode solicitar à Assembleia da República a aprovação de um voto de confiança sobre uma declaração de política geral ou sobre qualquer assunto relevante de interesse nacional.' },
  { n: 194, title: 'Moções de censura', part: OP, limit288: null,
    text: 'A Assembleia da República pode votar moções de censura ao Governo, por iniciativa de um quarto dos Deputados em efetividade de funções ou de qualquer grupo parlamentar. As moções só podem ser apreciadas quarenta e oito horas após a sua apresentação. Se não forem aprovadas, os seus signatários não podem apresentar outra durante a mesma sessão legislativa.' },
  { n: 195, title: 'Demissão do Governo', part: OP, limit288: null,
    text: 'Implicam a demissão do Governo o início de nova legislatura, a aceitação do pedido de demissão do Primeiro-Ministro, a sua morte ou impossibilidade física duradoura, a rejeição do programa do Governo, a não aprovação de uma moção de confiança e a aprovação de uma moção de censura por maioria absoluta. O Presidente só pode demitir o Governo para assegurar o regular funcionamento das instituições democráticas, ouvido o Conselho de Estado.' },
  { n: 197, title: 'Competência política do Governo', part: OP, limit288: null,
    text: 'Compete ao Governo referendar os atos do Presidente da República, negociar convenções internacionais, aprovar acordos internacionais, apresentar propostas de lei e de resolução à Assembleia da República, propor a sujeição a referendo e pronunciar-se sobre a declaração do estado de sítio ou de emergência.' },
  { n: 198, title: 'Competência legislativa do Governo', part: OP, limit288: null,
    text: 'Compete ao Governo fazer decretos-leis em matérias não reservadas à Assembleia da República, em matérias de reserva relativa mediante autorização desta, e decretos-leis de desenvolvimento das bases gerais contidas em leis. É da exclusiva competência do Governo a matéria respeitante à sua própria organização e funcionamento.' },
  { n: 201, title: 'Competência do Primeiro-Ministro', part: OP, limit288: null,
    text: 'Compete ao Primeiro-Ministro dirigir a política geral do Governo, coordenando e orientando a ação de todos os Ministros, dirigir o funcionamento do Governo e informar o Presidente da República acerca dos assuntos respeitantes à condução da política interna e externa do país.' },
  { n: 202, title: 'Função jurisdicional', part: OP, limit288: 'm',
    text: 'Os tribunais são os órgãos de soberania com competência para administrar a justiça em nome do povo, assegurando a defesa dos direitos e interesses legalmente protegidos dos cidadãos, reprimindo a violação da legalidade democrática e dirimindo os conflitos de interesses públicos e privados.' },
  { n: 203, title: 'Independência dos tribunais', part: OP, limit288: 'm',
    text: 'Os tribunais são independentes e apenas estão sujeitos à lei.' },
  { n: 221, title: 'Tribunal Constitucional — Definição', part: OP, limit288: 'l',
    text: 'O Tribunal Constitucional é o tribunal ao qual compete especificamente administrar a justiça em matérias de natureza jurídico-constitucional.' },
  { n: 222, title: 'Composição do Tribunal Constitucional', part: OP, limit288: 'm',
    text: 'O Tribunal Constitucional é composto por treze juízes, sendo dez designados pela Assembleia da República e três cooptados por estes. O mandato dos juízes tem a duração de nove anos e não é renovável. Os juízes gozam das garantias de independência, inamovibilidade, imparcialidade e irresponsabilidade.' },
  { n: 223, title: 'Competência do Tribunal Constitucional', part: OP, limit288: 'l',
    text: 'Compete ao Tribunal Constitucional apreciar a inconstitucionalidade e a ilegalidade das normas, verificar a legalidade da constituição de partidos políticos e das suas denominações, siglas e símbolos e ordenar a sua extinção, e verificar previamente a constitucionalidade e a legalidade dos referendos.' },
  { n: 225, title: 'Regime político-administrativo dos Açores e da Madeira', part: OP, limit288: 'o',
    text: 'O regime político-administrativo próprio dos arquipélagos dos Açores e da Madeira fundamenta-se nas suas características geográficas, económicas, sociais e culturais e nas históricas aspirações autonomistas das populações insulares. A autonomia regional não afeta a integridade da soberania do Estado e exerce-se no quadro da Constituição.' },
  { n: 227, title: 'Poderes das regiões autónomas', part: OP, limit288: 'o',
    text: 'As regiões autónomas são pessoas coletivas territoriais com poderes, definidos nos respetivos estatutos, para legislar no âmbito regional em matérias não reservadas aos órgãos de soberania, exercer poder tributário próprio e adaptar o sistema fiscal nacional, e dispor das receitas fiscais nelas cobradas ou geradas.' },
  { n: 235, title: 'Autarquias locais', part: OP, limit288: 'n',
    text: 'A organização democrática do Estado compreende a existência de autarquias locais. As autarquias locais são pessoas coletivas territoriais dotadas de órgãos representativos, que visam a prossecução de interesses próprios das populações respetivas.' },
  { n: 236, title: 'Categorias de autarquias locais', part: OP, limit288: 'n',
    text: 'No continente, as autarquias locais são as freguesias, os municípios e as regiões administrativas. As regiões autónomas dos Açores e da Madeira compreendem freguesias e municípios.' },
  { n: 255, title: 'Criação legal das regiões administrativas', part: OP, limit288: null,
    text: 'As regiões administrativas são criadas simultaneamente, por lei, a qual define os respetivos poderes, a composição, a competência e o funcionamento dos seus órgãos, podendo estabelecer diferenciações quanto ao regime aplicável a cada uma.' },
  { n: 256, title: 'Instituição em concreto das regiões', part: OP, limit288: null,
    text: 'A instituição em concreto das regiões administrativas depende da lei de criação e do voto favorável expresso pela maioria dos cidadãos eleitores que se tenham pronunciado em consulta direta, de alcance nacional e relativa a cada área regional. Em 1998, a regionalização foi rejeitada em referendo.' },
  // ───────────── GARANTIA E REVISÃO DA CONSTITUIÇÃO ─────────────
  { n: 277, title: 'Inconstitucionalidade por ação', part: GR, limit288: 'l',
    text: 'São inconstitucionais as normas que infrinjam o disposto na Constituição ou os princípios nela consignados.' },
  { n: 278, title: 'Fiscalização preventiva da constitucionalidade', part: GR, limit288: 'l',
    text: 'O Presidente da República pode requerer ao Tribunal Constitucional a apreciação preventiva da constitucionalidade de qualquer norma de decreto que lhe seja enviado para promulgação, no prazo de oito dias. O Tribunal deve pronunciar-se no prazo de vinte e cinco dias. Se se pronunciar pela inconstitucionalidade, o diploma é vetado e devolvido ao órgão que o aprovou.' },
  { n: 280, title: 'Fiscalização concreta da constitucionalidade', part: GR, limit288: 'l',
    text: 'Cabe recurso para o Tribunal Constitucional das decisões dos tribunais que recusem a aplicação de qualquer norma com fundamento na sua inconstitucionalidade ou que apliquem norma cuja inconstitucionalidade haja sido suscitada durante o processo.' },
  { n: 284, title: 'Competência e tempo de revisão', part: GR, limit288: null,
    text: 'A Assembleia da República pode rever a Constituição decorridos cinco anos sobre a data da publicação da última lei de revisão ordinária. Pode, contudo, assumir em qualquer momento poderes de revisão extraordinária por maioria de quatro quintos dos Deputados em efetividade de funções.' },
  { n: 285, title: 'Iniciativa da revisão', part: GR, limit288: null,
    text: 'A iniciativa da revisão compete aos Deputados. Apresentado um projeto de revisão constitucional, quaisquer outros terão de ser apresentados no prazo de trinta dias.' },
  { n: 286, title: 'Aprovação e promulgação', part: GR, limit288: null,
    text: 'As alterações da Constituição são aprovadas por maioria de dois terços dos Deputados em efetividade de funções e reunidas numa única lei de revisão. O Presidente da República não pode recusar a promulgação da lei de revisão.' },
  { n: 287, title: 'Novo texto da Constituição', part: GR, limit288: null,
    text: 'As alterações da Constituição são inseridas no lugar próprio, mediante as substituições, supressões e aditamentos necessários. A Constituição, no seu novo texto, é publicada conjuntamente com a lei de revisão.' },
  { n: 288, title: 'Limites materiais da revisão', part: GR, limit288: null,
    text: 'As leis de revisão constitucional terão de respeitar a independência nacional e a unidade do Estado, a forma republicana de governo, a separação das Igrejas do Estado, os direitos, liberdades e garantias, os direitos dos trabalhadores, a coexistência dos setores de propriedade, o sufrágio universal e o sistema de representação proporcional, o pluralismo político e o direito de oposição, a separação dos órgãos de soberania, a fiscalização da constitucionalidade, a independência dos tribunais e a autonomia local e regional.' },
  { n: 289, title: 'Limites circunstanciais da revisão', part: GR, limit288: null,
    text: 'Não pode ser praticado nenhum ato de revisão constitucional na vigência de estado de sítio ou de estado de emergência.' }
];

